import random,sys,itertools,json,subprocess
sys.path.insert(0,'/workspace/submission')

def ev(e,w):
    op=e['op']
    if op=='true': return True
    if op=='false': return False
    if op=='match': return list(w)==list(e['path'])
    if op=='startswith': return list(w[:len(e['path'])])==list(e['path'])
    if op=='endswith':
        p=list(e['path']); return len(w)>=len(p) and list(w[len(w)-len(p):])==p
    if op=='contains':
        p=list(e['path']); ww=list(w)
        if len(p)==0: return True
        return any(ww[i:i+len(p)]==p for i in range(len(ww)-len(p)+1))
    if op=='not': return not ev(e['arg'],w)
    if op=='and': return all(ev(a,w) for a in e['args'])
    if op=='or': return any(ev(a,w) for a in e['args'])
def brute(req,w_idx):
    sv=req['services']; w=[sv[i] for i in w_idx]
    al=any(ev(r['when'],w) for r in req['rules'] if r['action']=='allow')
    dr=any(ev(r['when'],w) for r in req['rules'] if r['action']=='drop')
    return al and not dr
def rand_expr(tokens,depth):
    ch=['true','false','match','startswith','endswith','contains'] if depth<=0 else ['true','false','match','startswith','endswith','contains','not','and','or']
    op=random.choice(ch)
    if op in ('true','false'): return {'op':op}
    if op in ('match','startswith','endswith','contains'):
        return {'op':op,'path':[random.choice(tokens) for _ in range(random.randint(0,3))] if tokens else []}
    if op=='not': return {'op':'not','arg':rand_expr(tokens,depth-1)}
    return {'op':op,'args':[rand_expr(tokens,depth-1) for _ in range(random.randint(0,3))]}

random.seed(555)
reqs=[]
for _ in range(200):
    A=random.randint(0,3); tokens=[f"t{i}" for i in range(A)]
    rules=[]
    for _ in range(random.randint(0,3)): rules.append({'action':'allow','when':rand_expr(tokens,2)})
    for _ in range(random.randint(0,3)): rules.append({'action':'drop','when':rand_expr(tokens,2)})
    reqs.append({'services':tokens,'rules':rules,'queries':[]})
payload=('\n'.join(json.dumps(r) for r in reqs)).encode()+b'\n'
p=subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=payload,capture_output=True,timeout=60)
assert p.returncode==0,p.stderr.decode()
outs=p.stdout.decode().splitlines()
assert len(outs)==len(reqs),(len(outs),len(reqs))
for req,line in zip(reqs,outs):
    res=json.loads(line)
    if not res.get('ok'):
        print("unexpected err",res,req); sys.exit(1)
    d=res['dfa']; A=len(req['services']); n=len(d['accept']); tr=d['next']; acc=d['accept']
    # canonical BFS
    order=[0]; seen={0}; q=[0]
    while q:
        s=q.pop(0)
        for c in range(A):
            t=tr[s][c]
            if t not in seen: seen.add(t); order.append(t); q.append(t)
    assert order==list(range(n)),("canon",req)
    assert len(set(tr[s][c] for s in range(n) for c in range(A)))<=n
    for L in range(6):
        for w in itertools.product(range(A),repeat=L):
            s=0
            for c in w: s=tr[s][c]
            assert acc[s]==brute(req,w),(req,w)
print("E2E fuzz passed 200 random requests")
